const blanketProductVariants=[
  {id:'fleece',name:'单层薄绒毯',hint:'单层短绒 · 轻软可折叠 · 窄缝包边',spec:'毯子类别：1条单层薄绒毯，单层短绒面料，轻软薄、可自然折叠，窄缝包边，表面哑光带轻微柔光；不是加厚双层毯或填充被芯。'},
  {id:'milk',name:'牛奶绒加厚毯',hint:'高克重双面绒 · 密实短绒 · 宽紧包边',spec:'毯子类别：1条牛奶绒加厚毯，高克重双面绒、密实短绒，绒向呈克制明暗，提花仅按用户实际资料，不默认新增格纹，毯身厚实挺括、折边圆润利落，宽而紧实的包边；不是单层薄毯或印花拉舍尔。'},
  {id:'cloud',name:'拉舍尔双层毛毯',hint:'双层复合 · 厚重蓬松 · 宽幅缎面包边',spec:'毯子类别：1条拉舍尔双层毛毯，两层绒面复合、中间无明显填充，厚重蓬松下垂感强，四周宽幅缎面包边，绒面平整可印花；不是单层薄毯或提花牛奶绒。'},
  {id:'gauze',name:'纱布毯',hint:'多层疏织 · 自然皱感 · 轻软垂坠',spec:'毯子类别：1条无填充纱布毯，多层轻软疏织纱布，细小经纬织纹、自然起皱肌理，窄布边缝线，轻软垂坠；无绒毛、缎边、填充或分仓绗缝。'}
];
function currentBlanketVariant(){return blanketProductVariants.find(v=>v.id===state.blanketVariant)||blanketProductVariants[0]}
function blanketSpecification(){return currentBlanketVariant().spec}
const blanketVariantPanel=document.createElement('section');blanketVariantPanel.id='blanketVariantPanel';blanketVariantPanel.className='set-variant-flyout quilt-variant-flyout blanket-variant-flyout';blanketVariantPanel.hidden=true;blanketVariantPanel.setAttribute('aria-labelledby','blanketVariantTitle');
blanketVariantPanel.innerHTML='<div class="set-variant-heading"><div><h2 id="blanketVariantTitle">毯子</h2><p>选择毯子款式 · 默认单层薄绒毯</p></div><button type="button" class="set-variant-close" aria-label="收起毯子分类">×</button></div><div class="set-variant-options"><h3>常见款式</h3><div class="set-variant-grid" role="group" aria-label="毯子款式"></div></div><div class="set-variant-footer"><span id="blanketVariantSelected"></span><button type="button" class="set-variant-done">完成选择</button></div>';
document.body.append(blanketVariantPanel);
function renderBlanketVariantControl(){const trigger=document.querySelector('[data-product="blanket"]');if(trigger){trigger.classList.add('has-blanket-variants');trigger.setAttribute('aria-expanded',String(!blanketVariantPanel.hidden));trigger.setAttribute('aria-controls','blanketVariantPanel');trigger.title=currentBlanketVariant().name+' · 点击展开毯子款式';renderChosenProductLabel(trigger,'毯子',currentBlanketVariant().name);}if(state.product==='blanket'){$('partsHint').textContent='1 条'+currentBlanketVariant().name+' · '+currentBlanketVariant().hint;document.querySelector('.group-angles .group-purpose').textContent=currentBlanketVariant().name+'构图 · 可多选 · AI 示例';}blanketVariantPanel.querySelector('#blanketVariantSelected').textContent='已选：'+currentBlanketVariant().name;}
function closeBlanketVariants(returnFocus=false){blanketVariantPanel.hidden=true;renderBlanketVariantControl();if(returnFocus)document.querySelector('[data-product="blanket"]')?.focus()}
function placeBlanketVariants(){placeProductSubmenu(blanketVariantPanel,document.querySelector('[data-product="blanket"]'),640,440);}
function selectBlanketVariant(id){if(state.busy||state.product!=='blanket'||!blanketProductVariants.some(v=>v.id===id))return;(state.productVariantChoices??={}).blanket=true;state.blanketVariant=id;if(state.fabricMode!=='selected'&&state.textureSource!=='upload'){state.fabric=id==='gauze'?'cotton':'velvet';updateFabric();}blanketVariantPanel.querySelectorAll('[data-blanket-variant]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.blanketVariant===id)));renderBlanketVariantControl();renderSelections();if(typeof closeBlanketVariants==='function')closeBlanketVariants(true);}
function openBlanketVariants(){if(state.busy||state.product!=='blanket')return;const grid=blanketVariantPanel.querySelector('.set-variant-grid');grid.replaceChildren();for(const item of blanketProductVariants){const b=document.createElement('button');b.type='button';b.className='set-variant-option blanket-variant-option';b.dataset.blanketVariant=item.id;b.setAttribute('aria-pressed',String(currentBlanketVariant().id===item.id));const picture=document.createElement('span');picture.className='blanket-variant-preview blanket-variant-preview-'+item.id;picture.setAttribute('role','img');picture.setAttribute('aria-label',item.name+'AI 结构示例');const name=document.createElement('strong');name.textContent=item.name;const hint=document.createElement('small');hint.textContent=item.hint;b.append(picture,name,hint);b.addEventListener('click',()=>selectBlanketVariant(item.id));grid.append(b)}blanketVariantPanel.hidden=false;placeBlanketVariants();renderBlanketVariantControl();}
blanketVariantPanel.querySelector('.set-variant-close').onclick=()=>closeBlanketVariants(true);blanketVariantPanel.querySelector('.set-variant-done').onclick=()=>closeBlanketVariants(true);
document.addEventListener('click',e=>{const product=e.target.closest('[data-product]');if(product&&!state.busy){if(product.dataset.product==='blanket'){if(blanketVariantPanel.hidden)openBlanketVariants();else closeBlanketVariants()}else closeBlanketVariants();renderBlanketVariantControl();return;}if(e.target.closest('#resetBtn')&&!state.busy)state.blanketVariant='fleece';if(!blanketVariantPanel.contains(e.target))closeBlanketVariants();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!blanketVariantPanel.hidden)closeBlanketVariants(true);if(e.key==='ArrowDown'&&e.target.closest('[data-product="blanket"]')&&!state.busy){e.preventDefault();openBlanketVariants();blanketVariantPanel.querySelector('[aria-pressed=true]')?.focus();}});
window.addEventListener('resize',()=>closeBlanketVariants());window.addEventListener('scroll',e=>{if(!blanketVariantPanel.contains(e.target))closeBlanketVariants()},{passive:true,capture:true});
new MutationObserver(renderBlanketVariantControl).observe($('products'),{childList:true});new MutationObserver(()=>{if(state.busy)closeBlanketVariants();renderBlanketVariantControl()}).observe($('generateBtn'),{attributes:true,attributeFilter:['disabled']});renderBlanketVariantControl();
